    func testBlocklistCreateOmitsUnsetOptions() throws {
        let json = String(decoding: try APIClient.encoder.encode(BlocklistCreate(historyId: 4, search: true)), as: UTF8.self)
        XCTAssertTrue(json.contains("\"history_id\":4"))
        XCTAssertFalse(json.contains("delete_current_file"))
        let withDelete = String(decoding: try APIClient.encoder.encode(BlocklistCreate(downloadId: 9, search: false, deleteCurrentFile: true)), as: UTF8.self)
        XCTAssertTrue(withDelete.contains("\"delete_current_file\":true"))
    }

    func testAlreadyRunningDetail() {
        let error = APIError.http(status: 409, body: #"{"detail": {"run_id": 12, "total": 4}}"#)
        XCTAssertEqual(error.detailRunId, 12)
        XCTAssertEqual(error.status, 409)
    }
